// SetMaxReadFrameSize sets the maximum size of a frame
// that will be read by a subsequent call to ReadFrame.
// It is the caller's responsibility to advertise this
// limit with a SETTINGS frame.
func (fr *Framer) SetMaxReadFrameSize(v uint32) {
	if v > maxFrameSize {
		v = maxFrameSize
	}
	fr.maxReadSize = v
}

// ErrorDetail returns a more detailed error of the last error
// returned by Framer.ReadFrame. For instance, if ReadFrame
// returns a StreamError with code PROTOCOL_ERROR, ErrorDetail
// will say exactly what was invalid. ErrorDetail is not guaranteed
// to return a non-nil value and like the rest of the http2 package,
// its return value is not protected by an API compatibility promise.
// ErrorDetail is reset after the next call to ReadFrame.
func (fr *Framer) ErrorDetail() error {
	return fr.errDetail
}

// ReadFrame reads a single frame. The returned Frame is only valid
// until the next call to ReadFrame.
//
// If the frame is larger than previously set with SetMaxReadFrameSize, the
// returned error is ErrFrameTooLarge. Other errors may be of type
// ConnectionError, StreamError, or anything else from the underlying
// reader.
func (fr *Framer) ReadFrame() (http2.Frame, error) {
	fr.errDetail = nil

	fh, err := readFrameHeader(fr.reader)
	if err != nil {
		return nil, err
	}
	if fh.Length > fr.maxReadSize {
		return nil, http2.ErrFrameTooLarge
	}
	// payload := fr.getReadBuf(fh.Length)
	var f http2.Frame
	var payloadForDump []byte // Keep payload for hex dump on error

	if fh.Type == http2.FrameData {
		f, err = parseDataFrame(fr.frameCache, fh, fr.reader)
	} else {
		var payload []byte
		payload, err = fr.reader.Next(int(fh.Length))
		if err != nil {
			return nil, err
		}
		payloadForDump = payload // Save for potential hex dump
		f, err = typeFrameParser(fh.Type)(fr.frameCache, fh, payload)
	}
	if err != nil {
		// On parse error, include hex dump of frame data for debugging
		if len(payloadForDump) > 0 {
			dumpStr := hexDump(payloadForDump, 256) // Dump first 256 bytes
			err = fmt.Errorf("%w; frame_type=%v stream_id=%d length=%d payload=%s",
				err, fh.Type, fh.StreamID, fh.Length, dumpStr)

